# Ratgeber: Mapping-Fachartikel. Wie Regelwerke zusammenhängen, die oft gemeinsam gelten.
# Grundlage: ENISA Technical Implementation Guidance v1.0 (DVO 2024/2690 -> ISO 27001:2022),
# BSI-Zuordnungstabelle ISO 27001 / IT-Grundschutz (Kompendium Edition 2023), Texte von NIS2,
# DSGVO, ISO 27001, ISO 22301 und BSI-Standard 200-4. Normtexte nur sinngemäß.

DATE = "2026-11-05"
TOPIC = "Regelwerke verbinden"

NIS2 = ("Richtlinie (EU) 2022/2555 (NIS2), EUR-Lex", "https://eur-lex.europa.eu/eli/dir/2022/2555/oj")
DVO = ("Durchführungsverordnung (EU) 2024/2690, EUR-Lex", "https://eur-lex.europa.eu/eli/reg_impl/2024/2690/oj")
ENISA = ("ENISA: NIS2 Technical Implementation Guidance", "https://www.enisa.europa.eu/publications/nis2-technical-implementation-guidance")
ISO27001 = ("ISO/IEC 27001:2022, ISO", "https://www.iso.org/standard/27001")
ISO22301 = ("ISO 22301:2019, ISO", "https://www.iso.org/standard/75106.html")
ISO27701 = ("ISO/IEC 27701, ISO", "https://www.iso.org/standard/27701")
DSGVO = ("Verordnung (EU) 2016/679 (DSGVO), EUR-Lex", "https://eur-lex.europa.eu/eli/reg/2016/679/oj")
BSI_GS = ("BSI: IT-Grundschutz und Zuordnungstabelle ISO 27001", "https://www.bsi.bund.de/grundschutz")
BSI_200_4 = ("BSI-Standard 200-4: Business Continuity Management", "https://www.bsi.bund.de/dok/bsi-standard-200-4")
BSIG = lambda n: (f"§ {n} BSIG, Gesetze im Internet", f"https://www.gesetze-im-internet.de/bsig_2025/__{n}.html")

ISO_NIS2 = dict(
    slug="ratgeber/iso-27001-nis2-mapping",
    nav="ISO 27001 und NIS2: Mapping",
    topic=TOPIC,
    keyword="ISO 27001 NIS2 Mapping",
    title="ISO 27001 und NIS2: Mapping und Lücken | CyberSecCheck",
    desc="Welche NIS2-Pflichten ein ISMS nach ISO 27001 abdeckt und was fehlt: die zehn Maßnahmen aus Art. 21 im Abgleich mit Anhang A, nach der Zuordnung der ENISA.",
    h1="ISO 27001 und NIS2: Was das Zertifikat abdeckt und was fehlt",
    lead="Wer ein ISMS nach ISO 27001 betreibt, hat für NIS2 einen großen Vorsprung. Aber nicht alles, was NIS2 verlangt, steckt in der Norm. Ein Abgleich entlang der offiziellen Zuordnung der EU-Agentur für Cybersicherheit (ENISA).",
    date=DATE,
    key=["Die zehn Risikomanagementmaßnahmen aus Art. 21 NIS2 lassen sich fast vollständig auf ISO 27001 abbilden.",
         "Die ENISA hat dazu eine Zuordnung veröffentlicht, betont aber: Sie ist keine Gleichwertigkeitsaussage.",
         "Nicht in ISO 27001: Registrierung, Meldefristen, persönliche Pflichten der Geschäftsleitung.",
         "Der Geltungsbereich eines Zertifikats kann kleiner sein als das, was NIS2 betrifft."],
    body=[
        ("h2", "Warum die beiden so gut zusammenpassen"),
        ("p", "Die NIS2-Richtlinie verlangt in Artikel 21 geeignete und verhältnismäßige Maßnahmen, um die Risiken für Netz- und Informationssysteme zu beherrschen. Sie sollen den Stand der Technik und, wo passend, europäische und internationale Normen berücksichtigen. ISO/IEC 27001 ist genau so eine Norm: ein Managementsystem, das von den Risiken ausgeht und passende Maßnahmen auswählt. Die zehn Mindestmaßnahmen aus Artikel 21 Absatz 2 finden sich deshalb zum großen Teil in den Abschnitten 4 bis 10 der Norm und in ihrem Anhang A wieder."),
        ("p", "Für bestimmte digitale Einrichtungen, etwa Cloud-Anbieter, Rechenzentren und Managed Service Provider, hat die EU-Kommission die Anforderungen in der Durchführungsverordnung (EU) 2024/2690 konkretisiert. Die ENISA hat in ihrer Technical Implementation Guidance jede Anforderung dieser Verordnung auf ISO 27001:2022 abgebildet. Diese Zuordnung ist die genaueste offizielle Quelle für den Abgleich, auch für Unternehmen, für die die Verordnung nicht unmittelbar gilt."),
        ("h2", "Die zehn Maßnahmen im Abgleich"),
        ("p", "Die folgende Übersicht fasst die ENISA-Zuordnung zusammen. Genannt sind die wichtigsten Abschnitte und Maßnahmen aus Anhang A, nicht jede einzelne Verknüpfung."),
        ("ul", ["**a) Risikoanalyse und Sicherheitskonzepte:** Leitlinie und Rollen (5.2, 5.3, A.5.1 bis A.5.4), Risikobeurteilung und Risikobehandlung (6.1.2, 6.1.3, 8.2, 8.3), interne Audits und Managementbewertung (9.2, 9.3).",
                "**b) Bewältigung von Sicherheitsvorfällen:** Planung, Beurteilung und Reaktion auf Vorfälle (A.5.24 bis A.5.26), Lernen aus Vorfällen und Sammeln von Beweisen (A.5.27, A.5.28), Melden von Ereignissen (A.6.8), Protokollierung und Überwachung (A.8.15 bis A.8.17).",
                "**c) Aufrechterhaltung des Betriebs:** Informationssicherheit bei Störungen und IKT-Bereitschaft für Business Continuity (A.5.29, A.5.30), Datensicherung und Redundanz (A.8.13, A.8.14).",
                "**d) Sicherheit der Lieferkette:** Lieferantenbeziehungen, Lieferantenvereinbarungen, IKT-Lieferkette und Überwachung von Lieferanten (A.5.19 bis A.5.22), ausgelagerte Entwicklung (A.8.30).",
                "**e) Erwerb, Entwicklung und Wartung:** Cloud-Dienste (A.5.23), Schwachstellenmanagement (A.8.8), Konfigurationsmanagement (A.8.9), Netzwerksicherheit und Trennung von Netzwerken (A.8.20, A.8.22), sichere Entwicklung (A.8.25 bis A.8.31), Änderungsmanagement (A.8.32).",
                "**f) Bewertung der Wirksamkeit:** Ziele (6.2), Überwachung und Messung (9.1), Managementbewertung (9.3).",
                "**g) Cyberhygiene und Schulungen:** Kompetenz und Bewusstsein (7.2, 7.3), Schulung (A.6.3), Schutz vor Schadsoftware (A.8.7).",
                "**h) Kryptografie:** Einsatz von Kryptografie (A.8.24), rechtliche Anforderungen (A.5.31).",
                "**i) Personal, Zugriffskontrolle, Anlagen:** Personalsicherheit (A.6.1 bis A.6.5), Inventar und Umgang mit Werten (A.5.9 bis A.5.14), Zugangssteuerung und Identitäten (A.5.15 bis A.5.18), physische Sicherheit (A.7.1 bis A.7.5).",
                "**j) Multi-Faktor-Authentifizierung und gesicherte Kommunikation:** sichere Authentisierung (A.8.5), Authentisierungsinformationen (A.5.17), privilegierte Zugänge (A.8.2)."]),
        ("p", "Wichtig: Die ENISA schreibt selbst, dass ihre Zuordnung keine Gleichwertigkeit bedeutet. Eine umgesetzte ISO-Maßnahme erfüllt nicht automatisch jede Detailanforderung der Verordnung. Die Zuordnung zeigt, wo Sie suchen müssen, nicht, dass Sie fertig sind."),
        ("h2", "Was ISO 27001 nicht abdeckt"),
        ("h3", "Registrierung und Meldefristen"),
        ("p", "Die Registrierung beim BSI nach § 33 BSIG kennt ISO 27001 nicht. Auch die Meldepflichten nach Artikel 23 NIS2 beziehungsweise § 32 BSIG gehen über die Norm hinaus. ISO 27001 verlangt einen geregelten Umgang mit Vorfällen und Kontakt zu Behörden, aber keine Frühwarnung binnen 24 Stunden, keine Meldung nach 72 Stunden und keinen Abschlussbericht nach einem Monat. Diese Fristen und Inhalte müssen Sie in Ihren Vorfallprozess einbauen. Details im Artikel [NIS2-Meldepflichten](/ratgeber/nis2-meldepflichten)."),
        ("h3", "Persönliche Pflichten der Geschäftsleitung"),
        ("p", "ISO 27001 verlangt Führung und Verpflichtung der obersten Leitung (Abschnitt 5.1) und eine Managementbewertung (9.3). NIS2 geht weiter: Die Leitung muss die Maßnahmen billigen, ihre Umsetzung überwachen, kann für Verstöße verantwortlich gemacht werden und muss selbst an Schulungen teilnehmen. Ein ISMS liefert die Grundlage, die persönliche Schulung und die förmliche Billigung müssen Sie aber gesondert nachweisen. Mehr dazu im Artikel [NIS2 für Geschäftsführer](/ratgeber/nis2-geschaeftsfuehrung-pflichten)."),
        ("h3", "Geltungsbereich"),
        ("p", "Bei ISO 27001 legen Sie den Geltungsbereich selbst fest. Er kann ein Standort, ein Produkt oder ein Geschäftsbereich sein. NIS2 betrifft dagegen die Einrichtung als Ganzes, also alle Netz- und Informationssysteme, die sie für ihren Betrieb oder ihre Dienste nutzt. Ein Zertifikat mit engem Geltungsbereich deckt deshalb nicht automatisch alles ab, was NIS2 verlangt. Prüfen Sie, ob Ihr Geltungsbereich erweitert werden sollte."),
        ("h3", "Tiefe der Lieferkettenprüfung"),
        ("p", "Artikel 21 Absatz 3 NIS2 verlangt, bei der Lieferkette die spezifischen Schwachstellen der einzelnen Anbieter, die Qualität ihrer Produkte und ihre Cybersicherheitspraxis einschließlich ihrer Entwicklungsprozesse zu berücksichtigen, außerdem die Ergebnisse koordinierter EU-Risikobewertungen. ISO 27001 behandelt Lieferanten im Anhang A, lässt die Tiefe aber offen. Für NIS2 sollten Sie die Bewertung kritischer Lieferanten entsprechend ausbauen."),
        ("h3", "Verhältnismäßigkeit und Stand der Technik"),
        ("p", "ISO 27001 lässt Ihnen die Wahl der Maßnahmen anhand Ihrer Risiken. NIS2 verlangt zusätzlich, dass die Maßnahmen dem Stand der Technik entsprechen und verhältnismäßig sind, gemessen an Risikoexposition, Größe, Eintrittswahrscheinlichkeit und Schwere möglicher Vorfälle. Halten Sie in der Risikobehandlung fest, warum Ihre Maßnahmen diesem Maßstab genügen."),
        ("h2", "So bringen Sie beides zusammen"),
        ("ol", ["**Die Erklärung zur Anwendbarkeit erweitern:** Ergänzen Sie eine Spalte, welche NIS2-Maßnahme (a bis j) eine Anhang-A-Maßnahme unterstützt. So sehen Sie auf einen Blick, wo Lücken sind.",
                "**Den Vorfallprozess anpassen:** Erheblichkeitskriterien, Fristen, Zuständigkeiten und Vorlagen für die Meldungen an das BSI.",
                "**Den Geltungsbereich prüfen:** Deckt er alles ab, was NIS2 betrifft?",
                "**Die Geschäftsleitung einbinden:** Billigung im Protokoll, regelmäßiger Bericht, eigene Schulung.",
                "**Die Lieferantenbewertung schärfen:** kritische Lieferanten identifizieren und tiefer prüfen."]),
        ("p", "Die [ISMS-Suite](/#software) bildet genau diesen Gedanken ab: Eine Maßnahme wird einmal gepflegt und mit den Anforderungen aus ISO 27001 und NIS2 gleichzeitig verknüpft. Das NIS2-Cockpit zeigt, welche Pflichten über ISO-Maßnahmen abgedeckt sind und wo eine Zuordnung oder Maßnahme fehlt."),
        ("p", "Wie ich Sie dabei unterstütze, steht auf den Seiten [ISO 27001 Beratung](/iso-27001-beratung-muenchen) und [NIS2 Beratung](/nis2-beratung-muenchen)."),
    ],
    faq=[("Ist ein ISO-27001-Zertifikat für NIS2 Pflicht?", "Nein. NIS2 verlangt kein Zertifikat. Es ist aber ein anerkannter Nachweis, dass ein großer Teil der Maßnahmen systematisch umgesetzt ist."),
         ("Gilt die Durchführungsverordnung 2024/2690 für mein Unternehmen?", "Unmittelbar gilt sie nur für bestimmte digitale Einrichtungen, etwa Cloud-Anbieter, Rechenzentren, Managed Service Provider und Vertrauensdiensteanbieter. Für andere Unternehmen ist sie trotzdem eine gute Orientierung, was der Stand der Technik sein kann."),
         ("Wir haben ein Zertifikat. Was sollten wir zuerst tun?", "Den Vorfallprozess um die NIS2-Meldefristen ergänzen und prüfen, ob der Geltungsbereich des Zertifikats alles abdeckt, was unter NIS2 fällt. Das sind die häufigsten Lücken.")],
    sources=[NIS2, DVO, ENISA, ISO27001, BSIG(30), BSIG(32)],
    related=[("ISO 27001 Beratung München", "/iso-27001-beratung-muenchen", "Das ISMS aufbauen oder erweitern"),
             ("NIS2 Beratung München", "/nis2-beratung-muenchen", "Die Lücken schließen"),
             ("NIS2 und DSGVO", "/ratgeber/nis2-dsgvo-meldepflichten", "Zwei Meldepflichten, ein Vorfall")],
)

